/**
 * OpenCode Bridge - extension entry point.
 *
 * Two server connection modes:
 *  - "managed" (default): The extension starts its OWN private `opencode serve`
 *    child on a free auto-chosen port with a random password. The password is
 *    generated by the extension and passed ONLY via the OPENCODE_SERVER_PASSWORD
 *    env var to the child process.
 *  - "external": Connect to an existing server at hostname:port. Password
 *    lookup: context.secrets → env OPENCODE_SERVER_PASSWORD → prompt user.
 *
 * Activation flow:
 *  1. Read settings (hostname, port, autoStartServer, opencodePath, model,
 *     serverMode, debug).
 *  2. Resolve basic-auth header (secret first, then env var).
 *  3. Managed mode: find free port, generate random password, spawn own
 *    `opencode serve`, wait for readiness. External mode: check reachability
 *    at hostname:port.
 *  4. Create + connect the SDK client.
 *  5. Register the sidebar chat view, commands, and Output channel.
 *  6. On deactivate, kill only the process we spawned (managed mode).
 */

import * as vscode from "vscode";
import { OpenCodeChatView } from "./chatView.js";
import { OpencodeBridgeClient } from "./client.js";
import {
  buildBaseUrl,
  findFreePort,
  generateRandomPassword,
  isServerReachable,
  spawnOpencodeServe,
  waitForServer,
  resolveAuthHeader,
  ManagedServer,
  ServerMode,
  outputChannel,
  logError,
  logDebug,
  OUTPUT_CHANNEL_NAME,
  authHeaderFromPassword,
  envAuthHeaderFromProcess,
} from "./server.js";

let chatView: OpenCodeChatView | undefined;
let managedServer: ManagedServer | undefined;
let client: OpencodeBridgeClient | undefined;
let currentSessionID: string | undefined;
let outputChan: vscode.OutputChannel | undefined;
let currentMode: ServerMode = "managed";
let managedPassword: string | undefined; // in-memory only, never logged

/** Resolve settings with sane defaults. */
function getSettings() {
  const cfg = vscode.workspace.getConfiguration("opencodeBridge");
  return {
    port: cfg.get<number>("port", 4096),
    hostname: cfg.get<string>("hostname", "127.0.0.1"),
    autoStartServer: cfg.get<boolean>("autoStartServer", true),
    opencodePath: cfg.get<string>("opencodePath", "opencode"),
    model: cfg.get<string>("model", ""),
    serverMode: (cfg.get<string>("serverMode", "managed") as ServerMode),
    debug: cfg.get<boolean>("debug", false),
  };
}

function firstWorkspaceFolder(): string | undefined {
  const folder = vscode.workspace.workspaceFolders?.[0];
  return folder ? folder.uri.fsPath : undefined;
}

/**
 * Managed mode: find a free port, generate a random password, spawn our own
 * `opencode serve` child with OPENCODE_SERVER_PASSWORD set in its env, wait
 * for readiness. Returns the base URL and auth header.
 */
async function ensureManagedServer(): Promise<{
  baseUrl: string;
  authHeader: string;
}> {
  const { opencodePath, debug } = getSettings();
  const cwd = firstWorkspaceFolder();

  // Find a free port by binding to port 0.
  const port = await findFreePort("127.0.0.1");
  logDebug(
    `managed mode: found free port ${port}`,
    debug
  );

  // Generate a random password (never logged).
  const password = generateRandomPassword();
  managedPassword = password;
  const authHeader = authHeaderFromPassword(password);

  logDebug(
    `managed mode: spawning "${opencodePath} serve --hostname 127.0.0.1 --port ${port}" cwd=${cwd ?? process.cwd()}`,
    debug
  );

  const child = spawnOpencodeServe(opencodePath, port, "127.0.0.1", cwd, password);

  managedServer = new ManagedServer({
    mode: "managed",
    hostname: "127.0.0.1",
    port,
    baseUrl: buildBaseUrl("127.0.0.1", port),
    authHeader,
    spawnedProcess: child,
    password,
  });

  const ready = await waitForServer("127.0.0.1", port, authHeader, 10_000);
  if (!ready) {
    managedServer.dispose();
    managedServer = undefined;
    managedPassword = undefined;
    throw new Error(
      `OpenCode server (managed mode) did not become reachable on port ${port} within 10s. Check that "${opencodePath}" is installed and see the "${OUTPUT_CHANNEL_NAME}" output channel for details.`
    );
  }

  logDebug(`managed mode: server ready on port ${port}`, debug);
  return { baseUrl: buildBaseUrl("127.0.0.1", port), authHeader };
}

/**
 * External mode: check reachability at hostname:port (without auth — 401
 * means reachable). Returns baseUrl. Auth is handled separately by
 * connectWithAuthRetry.
 */
async function ensureExternalServer(): Promise<string> {
  const { port, hostname, debug } = getSettings();

  // Try without auth first — 401 means the server is up but needs auth.
  const reachableNoAuth = await isServerReachable(hostname, port, undefined);
  if (!reachableNoAuth.reachable) {
    // Maybe it needs auth to even respond to /api/info? Try with env/secret auth.
    const authHeader = await resolveAuthHeaderPlaceholder();
    const reachableWithAuth = await isServerReachable(hostname, port, authHeader);
    if (!reachableWithAuth.reachable) {
      throw new Error(
        `No OpenCode server reachable at ${hostname}:${port}. Start one manually (e.g. \`opencode serve --port ${port}\`) or switch to managed mode (opencodeBridge.serverMode = "managed").`
      );
    }
    logDebug(`external mode: server reachable at ${hostname}:${port} (with auth, status ${reachableWithAuth.statusCode})`, debug);
    return buildBaseUrl(hostname, port);
  }

  logDebug(`external mode: server reachable at ${hostname}:${port} (status ${reachableNoAuth.statusCode})`, debug);
  return buildBaseUrl(hostname, port);
}

/** Placeholder: resolve auth header without a real ExtensionContext.
 * Used only for the initial reachability probe in external mode.
 */
async function resolveAuthHeaderPlaceholder(): Promise<string | undefined> {
  // Try env var only (secrets require a real ExtensionContext).
  return envAuthHeaderFromProcess();
}

/** Try connecting with the given auth header. If 401, prompt user for password and retry once. */
async function connectWithAuthRetry(
  context: vscode.ExtensionContext,
  baseUrl: string,
  initialAuthHeader: string | undefined,
  mode: ServerMode
): Promise<string | undefined> {
  let authHeader = initialAuthHeader;

  const tryConnect = async (ah: string | undefined): Promise<boolean> => {
    // Test connectivity with a cheap request.
    try {
      const probeRes = await fetch(`${baseUrl}/api/info`, {
        method: "GET",
        headers: ah ? { Authorization: ah } : {},
      });
      if (probeRes.ok) {
        return true;
      }
      if (probeRes.status === 401 || probeRes.status === 403) {
        // Auth failure — do not retry silently.
        return false;
      }
      // Other server error — still consider connected.
      return true;
    } catch {
      return false;
    }
  };

  const connected = await tryConnect(authHeader);
  if (connected) return authHeader;

  // If auth failed or no auth and mode is external, prompt user.
  if (mode === "external") {
    const password = await promptForPassword(context);
    if (password) {
      authHeader = authHeaderFromPassword(password);
      const connected2 = await tryConnect(authHeader);
      if (connected2) return authHeader;
    }
  }

  return authHeader; // may be undefined — caller will surface error
}

/** Prompt user for server password, store in context.secrets. */
async function promptForPassword(context: vscode.ExtensionContext): Promise<string | undefined> {
  const password = await vscode.window.showInputBox({
    prompt: "OpenCode server password",
    password: true,
    placeHolder: "e.g. a-long-secret",
  });
  if (password === undefined) return undefined; // cancelled
  if (!password) {
    void vscode.window.showWarningMessage("OpenCode Bridge: Password cannot be empty.");
    return undefined;
  }
  try {
    await context.secrets.store("opencodeBridge.serverPassword", password);
    outputChan?.appendLine("[opencode-bridge] server password stored in secrets");
    return password;
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logError(`Failed to store password: ${msg}`);
    void vscode.window.showErrorMessage(`OpenCode Bridge: failed to store password: ${msg}`);
    return undefined;
  }
}

export async function activate(context: vscode.ExtensionContext): Promise<void> {
  console.log("[opencode-bridge] activating");
  outputChan = outputChannel();
  outputChan.appendLine("[opencode-bridge] activating");
  outputChan.show(true);

  const settings = getSettings();
  currentMode = settings.serverMode;
  outputChan.appendLine(
    `[opencode-bridge] settings: mode=${settings.serverMode} ${settings.hostname}:${settings.port} autoStart=${settings.autoStartServer} debug=${settings.debug}`
  );

  let baseUrl: string;
  let authHeader: string | undefined;

  if (currentMode === "managed") {
    // Managed mode: always start our own server.
    try {
      const result = await ensureManagedServer();
      baseUrl = result.baseUrl;
      authHeader = result.authHeader;
      outputChan.appendLine(`[opencode-bridge] managed server started on ${baseUrl}`);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      outputChan.appendLine(`[opencode-bridge] managed server start failed: ${msg}`);
      void vscode.window.showErrorMessage(`OpenCode Bridge: ${msg}`);
      // Still register commands so user can retry / switch mode.
      baseUrl = buildBaseUrl(settings.hostname, settings.port);
      authHeader = undefined;
    }
  } else {
    // External mode: connect to existing server.
    try {
      baseUrl = await ensureExternalServer();
      // Auth is resolved in connectWithAuthRetry below.
      authHeader = undefined;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      outputChan.appendLine(`[opencode-bridge] external server check failed: ${msg}`);
      void vscode.window.showErrorMessage(`OpenCode Bridge: ${msg}`);
      baseUrl = buildBaseUrl(settings.hostname, settings.port);
      authHeader = undefined;
    }
  }

  // Try connecting with auth; prompt user on 401 in external mode.
  authHeader = await connectWithAuthRetry(context, baseUrl, authHeader, currentMode);

  client = new OpencodeBridgeClient(baseUrl, settings.debug);
  client.connect(authHeader);

  // Restore persisted model choice from globalState, fallback to setting.
  const persisted = context.globalState.get<{ providerID: string; modelID: string } | null>(
    "opencodeBridge.selectedModel",
    null
  );
  const modelFromSetting = settings.model
    ? parseModelString(settings.model)
    : null;
  const selectedModel = persisted ?? modelFromSetting;

  chatView = new OpenCodeChatView({
    client,
    extensionPath: context.extensionPath,
    sessionID: currentSessionID,
    debug: settings.debug,
    serverUrl: baseUrl,
    workspaceDir: firstWorkspaceFolder(),
    mode: currentMode,
    onSetPassword: async () => {
      await handleSetServerPassword(context);
      // After setting password, reconnect the client.
      const newAuth = await resolveAuthHeader(context);
      if (newAuth) {
        client?.setAuthHeader(newAuth);
        authHeader = newAuth;
        // Refresh providers in the chat view.
        chatView?.refreshProviders();
      }
    },
    onEnterPassword: async () => {
      await handleSetServerPassword(context);
      const newAuth = await resolveAuthHeader(context);
      if (newAuth) {
        client?.setAuthHeader(newAuth);
        authHeader = newAuth;
        chatView?.refreshProviders();
      }
    },
  });
  if (selectedModel) {
    chatView.setSelectedModel(selectedModel);
  }
  chatView.register(context);

  // Commands.
  context.subscriptions.push(
    vscode.commands.registerCommand("opencode-bridge.openChat", async () => {
      await vscode.commands.executeCommand("workbench.view.extension.opencode-bridge-sidebar");
    }),
    vscode.commands.registerCommand(
      "opencode-bridge.askSelection",
      async () => {
        await handleAskSelection();
      }
    ),
    vscode.commands.registerCommand("opencode-bridge.addFileContext", async () => {
      await handleAddFileContext();
    }),
    vscode.commands.registerCommand("opencode-bridge.setServerPassword", async () => {
      await handleSetServerPassword(context);
    }),
    vscode.commands.registerCommand("opencode-bridge.clearServerPassword", async () => {
      await handleClearServerPassword(context);
    })
  );

  // Watch for setting changes.
  const configWatcher = vscode.workspace.onDidChangeConfiguration((e) => {
    if (e.affectsConfiguration("opencodeBridge.model")) {
      const newModel = vscode.workspace
        .getConfiguration("opencodeBridge")
        .get<string>("model", "");
      const parsed = newModel ? parseModelString(newModel) : null;
      if (parsed) {
        context.globalState.update("opencodeBridge.selectedModel", parsed);
        chatView?.setSelectedModel(parsed);
        outputChan?.appendLine(`[opencode-bridge] model updated: ${parsed.providerID}/${parsed.modelID}`);
      }
    }
    if (e.affectsConfiguration("opencodeBridge.debug")) {
      const debug = vscode.workspace
        .getConfiguration("opencodeBridge")
        .get<boolean>("debug", false);
      client?.setDebug(debug);
      outputChan?.appendLine(`[opencode-bridge] debug=${debug}`);
    }
    if (e.affectsConfiguration("opencodeBridge.serverMode")) {
      void vscode.window.showInformationMessage(
        "OpenCode Bridge: serverMode changed. Reload the window to apply the new mode."
      );
    }
  });
  context.subscriptions.push(configWatcher);

  // Expose for testing / programmatic use.
  (globalThis as any).__opencodeBridge = {
    client,
    getSessionID: () => currentSessionID,
    setSessionID: (id: string) => {
      currentSessionID = id;
    },
    getMode: () => currentMode,
    getManagedPassword: () => managedPassword, // test-only, never logged
  };

  console.log("[opencode-bridge] activated");
  outputChan.appendLine("[opencode-bridge] activated");
}

export function deactivate(): void {
  console.log("[opencode-bridge] deactivating");
  outputChan?.appendLine("[opencode-bridge] deactivating");
  if (managedServer) {
    managedServer.dispose();
    managedServer = undefined;
  }
  managedPassword = undefined;
  chatView?.dispose();
  chatView = undefined;
  client = undefined;
  outputChan?.hide();
}

/* ------------------------------------------------------------------ */
/* Editor integration commands                                        */
/* ------------------------------------------------------------------ */

async function handleAskSelection(): Promise<void> {
  const editor = vscode.window.activeTextEditor;
  if (!editor) {
    void vscode.window.showWarningMessage("OpenCode Bridge: No active editor.");
    return;
  }
  const selection = editor.selection;
  const doc = editor.document;
  const selectedText = doc.getText(selection);
  if (!selectedText || !selectedText.trim()) {
    void vscode.window.showWarningMessage("OpenCode Bridge: No text selected.");
    return;
  }

  const start = selection.start;
  const end = selection.end;
  const rangeInfo = `${doc.uri.fsPath}:${start.line + 1}-${end.line + 1}`;

  const question = await vscode.window.showInputBox({
    prompt: `Ask OpenCode about the selection (${rangeInfo})`,
    placeHolder: "e.g. Explain this function and suggest improvements",
  });
  if (!question) return;

  const contextStr = `File: ${doc.uri.fsPath}\nLines: ${start.line + 1}-${end.line + 1}\nSelection:\n${selectedText}`;
  await sendToChat(`${question}\n\nContext:\n${contextStr}`);
}

async function handleAddFileContext(): Promise<void> {
  const editor = vscode.window.activeTextEditor;
  if (!editor) {
    void vscode.window.showWarningMessage("OpenCode Bridge: No active editor.");
    return;
  }
  const doc = editor.document;
  const contextStr = `File: ${doc.uri.fsPath}\n\n${doc.getText()}`;
  const question = await vscode.window.showInputBox({
    prompt: "Ask OpenCode about the current file",
    placeHolder: "e.g. Summarize this file",
  });
  if (!question) return;
  await sendToChat(`${question}\n\nContext:\n${contextStr}`);
}

/** "OpenCode: Set Server Password" - stores password in context.secrets. */
async function handleSetServerPassword(context: vscode.ExtensionContext): Promise<void> {
  const password = await vscode.window.showInputBox({
    prompt: "OpenCode server password",
    password: true,
    placeHolder: "e.g. a-long-secret",
  });
  if (password === undefined) return; // user cancelled
  if (!password) {
    void vscode.window.showWarningMessage("OpenCode Bridge: Password cannot be empty.");
    return;
  }
  try {
    await context.secrets.store("opencodeBridge.serverPassword", password);
    void vscode.window.showInformationMessage(
      "OpenCode Bridge: Server password stored securely."
    );
    outputChan?.appendLine("[opencode-bridge] server password stored in secrets");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logError(`Failed to store password: ${msg}`);
    void vscode.window.showErrorMessage(`OpenCode Bridge: failed to store password: ${msg}`);
  }
}

/** "OpenCode: Clear Server Password" - removes password from context.secrets. */
async function handleClearServerPassword(context: vscode.ExtensionContext): Promise<void> {
  try {
    await context.secrets.delete("opencodeBridge.serverPassword");
    void vscode.window.showInformationMessage(
      "OpenCode Bridge: Server password cleared."
    );
    outputChan?.appendLine("[opencode-bridge] server password cleared from secrets");
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    logError(`Failed to clear password: ${msg}`);
    void vscode.window.showErrorMessage(`OpenCode Bridge: failed to clear password: ${msg}`);
  }
}

async function sendToChat(text: string): Promise<void> {
  if (!chatView) {
    void vscode.window.showWarningMessage("OpenCode Bridge: Chat view not ready.");
    return;
  }
  await vscode.commands.executeCommand(
    "workbench.view.extension.opencode-bridge-sidebar"
  );
  await chatView.sendMessage(text);
}

/** Parse a "providerID/modelID" string into components. */
function parseModelString(s: string): { providerID: string; modelID: string } | null {
  const idx = s.indexOf("/");
  if (idx <= 0 || idx === s.length - 1) return null;
  return { providerID: s.slice(0, idx), modelID: s.slice(idx + 1) };
}
